// ===== Configuração (preencha no seu n8n; nunca no repositório) =====
const SENHA = '';  // senha da área de emissão; vazia = área desligada (404)
// ====================================================================

// Senha única do emissor, pela caixa de login do navegador (Basic Auth).
// Ao atingir o limite de senhas erradas, o visitante fica bloqueado pela
// janela, inclusive para a senha certa. O bloqueio expira sozinho.
const LIMITE = 10;      // senhas erradas por visitante
const JANELA = 60000;   // ms

const req = $input.first().json;
const negar = (status, mensagem) => [{ json: { autorizado: false, status, mensagem } }];
if (!SENHA) return negar(404, 'Não encontrado.');

// IP real do visitante: último endereço do X-Forwarded-For (ver validar-preparar).
const headers = req.headers || {};
const encaminhado = String(headers['x-forwarded-for'] || '').split(',').map(s => s.trim()).filter(Boolean);
const ip = encaminhado.pop() || String(headers['x-real-ip'] || 'desconhecido');

// ponytail: contador nos dados estáticos do fluxo, sem trava entre execuções
// simultâneas. Teto: limite aproximado; se precisar de exatidão, usar a versão Python.
const dados = $getWorkflowStaticData('global');
const agora = Date.now();
const falhas = dados.falhas || {};
for (const k of Object.keys(falhas)) {
  falhas[k] = falhas[k].filter(t => agora - t < JANELA);
  if (!falhas[k].length) delete falhas[k];
}
dados.falhas = falhas;
const minhas = falhas[ip] || [];

// O bloqueio vem antes da comparação: durante a janela, nem a senha certa é testada.
if (minhas.length >= LIMITE) return negar(429, 'Muitas tentativas. Aguarde um minuto.');

const auth = String(headers.authorization || '');
// Sem credencial é só o navegador pedindo a senha; não conta como tentativa.
if (!auth.startsWith('Basic ')) return negar(401, 'Senha necessária.');
const senha = Buffer.from(auth.slice(6), 'base64').toString('utf8').split(':').slice(1).join(':');
if (senha === SENHA) return [{ json: { autorizado: true } }];

minhas.push(agora);
falhas[ip] = minhas;
return negar(401, 'Senha necessária.');
